  `ref_certificacion` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Referencia del certificado dentro del historial de ese guía',
  `registrada_en` datetime(6) NOT NULL COMMENT 'Instante local de registro usado para verificar la acreditación',
  `aplica_desde` datetime(6) NOT NULL COMMENT 'Inicio inclusivo del período en que el guía atiende al grupo',
  `aplica_hasta` datetime(6) DEFAULT NULL COMMENT 'Fin exclusivo del período. NULL indica asignación sin fin registrado'
) ;

